{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or Replace Table andamen_db.maplemonk.Andamen_db_SKU_Visibility_Data as With GA4 as( Select last_day(TO_DATE(Date, \'YYYYMMDD\')) AS Date, split(coalesce(coalesce(fi.sku,fii.sku,fiii.sku),itemid),\'-\')[0]::string as SKU, sum(ifnull(sessions,0)) as SESSIONS, sum(ifnull(totalusers,0)) as TOTALUSERS, sum(ifnull(itemsviewed,0)) as itemsviewed, sum(ifnull(ITEMSADDEDTOCART,0)) as ITEMSADDEDTOCART, sum(ifnull(ITEMSCHECKEDOUT,0)) as ITEMSCHECKEDOUT, sum(ifnull(ENGAGEDSESSIONS,0)) as ENGAGEDSESSIONS from andamen_db.maplemonk.andamen_products_funnel_metrics fm left join ( select product_id, sku from andamen_db.maplemonk.andamen_db_shopify_fact_items Qualify row_number() over(partition by product_id order by 1) = 1 )fi on ifnull(split(fm.itemid,\'_\')[2]::string,\'vamsi\') = fi.product_id::string left join ( select product_id, sku from andamen_db.maplemonk.andamen_db_shopify_fact_items Qualify row_number() over(partition by product_id order by 1) = 1 )fii on ifnull(split(fm.itemid,\'_\')[3]::string,\'vamsi\') = fii.product_id::string left join ( select product_id, sku from andamen_db.maplemonk.andamen_db_shopify_fact_items Qualify row_number() over(partition by lower(sku) order by 1) = 1 )fiii on lower(fm.itemid) = lower(fiii.sku::string) group by 1,2 ), SalesData as ( Select last_day(order_timestamp ::date) as Date ,split(sku,\'-\')[0]::string as SKU ,sum(ifnull(quantity,0)) as Quantity ,sum(ifnull(line_item_sales,0)) as MRP ,sum(ifnull(total_sales,0)) as SELLING_PRICE ,sum(ifnull(line_item_sales,0)) - sum(ifnull(total_sales,0)) as Discount from andamen_db.MAPLEMONK.andamen_db_SHOPIFY_FACT_ITEMS group by 1 ,2 ), FinalResult as ( (select coalesce(ga.date,sd.date) as Date, upper(coalesce(ga.sku,sd.sku)) as SKU, \'Shopify\' as marketplace, SESSIONS, itemsviewed, ITEMSADDEDTOCART, ITEMSCHECKEDOUT, Quantity, MRP, SELLING_PRICE, Discount from GA4 ga full outer join SalesData sd on ga.date = sd.date and trim(lower(ga.sku)) = trim(lower(sd.sku)) ) UNION ALL select last_day(LEFT(\"Time Period\", 10)::date) AS Date, trim(upper(\"Parent SKU\")) as SKU, \'Myntra\' as Marketplace, null as sessions, sum(ifnull(nullif(\"List Page Count\",\'\'),0)) as Views, sum(ifnull(nullif(\"PDP Count\",\'\'),0)) as ITEMSADDEDTOCART, sum(ifnull(nullif(\"PDP Count\",\'\'),0)) as ITEMSCHECKEDOUT, sum(ifnull(nullif(\"Units Sold\",\'\'),0)) as Quantity, sum(ifnull(nullif(mrp,\'\'),0)) as MRP, sum(ifnull(nullif(\"Selling Price\",\'\'),0)) as SellingPrice, sum(ifnull(nullif(mrp,\'\'),0)) - sum(ifnull(nullif(\"Selling Price\",\'\'),0)) discount from andamen_db.maplemonk.andamen_db_myntra_funnel_data group by 1,2 ) select fr.*,sm.* from FinalResult fr left join ( select upper(commonsku) skucode ,upper(product_name) name ,upper(category) category ,upper(sub_category) sub_category ,upper(collection) Collection ,upper(season) season ,try_to_date(launch_date, \'DD Mon YYYY\') LAUNCH_DATE from andamen_db.MAPLEMONK.sku_master QUALIFY row_number() over (partition by trim(upper(commonsku)) order by 1) = 1 )sm on trim(upper(sm.skucode)) = trim(upper(fr.sku)); Create Or Replace Table andamen_db.maplemonk.andamen_db_FRSN_Category_Data as With SalesData as ( select split(split(sku,\'_\')[0],\'-\')[0]::string as SKU ,Category ,order_date::date as Date ,mp.LAUNCH_DATE ,sum(ifnull(quantity,0)) Quantity from andamen_db.maplemonk.andamen_db_sales_consolidated sd left join ( select upper(commonsku) skucode ,upper(CATEGORY) Category ,try_to_date(launch_date, \'DD Mon YYYY\') LAUNCH_DATE from andamen_db.MAPLEMONK.sku_master QUALIFY row_number() over (partition by upper(commonsku) order by 1) = 1 )mp on lower(trim(split(split(sd.sku,\'_\')[0],\'-\')[0]::string)) = lower(trim(mp.skucode)) group by 1,2,3,4 ), ActualSalesData as ( select sku, Category, LAUNCH_DATE, \'W1\' as Week, sum(ifnull(Quantity,0))/7 as ROS from SalesData where DATE BETWEEN LAUNCH_DATE AND DATEADD(DAY, 6, LAUNCH_DATE) group by 1,2,3 UNION ALL select sku, Category, LAUNCH_DATE, \'W2\' as Week, sum(ifnull(Quantity,0))/7 as Quantity from SalesData where DATE BETWEEN DATEADD(DAY, 7, LAUNCH_DATE) AND DATEADD(DAY, 13, LAUNCH_DATE) group by 1,2,3 UNION ALL select sku, Category, LAUNCH_DATE, \'W3\' as Week, sum(ifnull(Quantity,0))/7 as Quantity from SalesData where DATE BETWEEN DATEADD(DAY, 14, LAUNCH_DATE) AND DATEADD(DAY, 20, LAUNCH_DATE) group by 1,2,3 UNION ALL select sku, Category, LAUNCH_DATE, \'W4\' as Week, sum(ifnull(Quantity,0))/7 as Quantity from SalesData where DATE BETWEEN DATEADD(DAY, 21, LAUNCH_DATE) AND DATEADD(DAY, 27, LAUNCH_DATE) group by 1,2,3 UNION ALL select sku, Category, LAUNCH_DATE, \'M1\' as Week, sum(ifnull(Quantity,0))/30 as Quantity from SalesData where DATE BETWEEN DATEADD(DAY, 0, LAUNCH_DATE) AND DATEADD(DAY, 29, LAUNCH_DATE) group by 1,2,3 UNION ALL select sku, Category, LAUNCH_DATE, \'M2\' as Week, sum(ifnull(Quantity,0))/30 as Quantity from SalesData where DATE BETWEEN DATEADD(DAY, 30, LAUNCH_DATE) AND DATEADD(DAY, 59, LAUNCH_DATE) group by 1,2,3 UNION ALL select sku, Category, LAUNCH_DATE, \'M3\' as Week, sum(ifnull(Quantity,0))/30 as Quantity from SalesData where DATE BETWEEN DATEADD(DAY, 60, LAUNCH_DATE) AND DATEADD(DAY, 89, LAUNCH_DATE) group by 1,2,3 UNION ALL select sku, Category, LAUNCH_DATE, \'Lifetime ROS\' as Week, sum(ifnull(Quantity,0))/max((DATEDIFF(day, LAUNCH_DATE, current_date))) as Quantity from SalesData where DATE BETWEEN DATEADD(DAY, 0, LAUNCH_DATE) AND current_date group by 1,2,3 ), TargetsData as ( select upper(FRSN) as FRSN, upper(period) Period, upper(CATEGORY) Category, cast(replace(\"lowerlimit(inclusive)\",\',\',\'\') as float) as Lower, cast(replace(\"upperlimit(exclusive)\",\',\',\'\') as float) as Upper from andamen_db.maplemonk.andamen_db_frsn_mapping QUALIFY ROW_NUMBER() over(partition by upper(FRSN),upper(period),upper(CATEGORY),replace(\"lowerlimit(inclusive)\",\',\',\'\'),replace(\"upperlimit(exclusive)\",\',\',\'\') order by 1) = 1 ) Select asd.* ,td.Lower ,td.upper ,FRSN from ActualSalesData asd left join TargetsData Td on lower(trim(asd.Category)) = lower(trim(td.Category)) and lower(trim(asd.week)) = lower(trim(td.Period)) and ros >= Lower and ros <= upper ;",
                    "transaction": true
                }
            ) }}
